const alMulk: VerseText[] = [
  { surahNumber: 67, verseNumber: 1, arabic: "تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", translation: "Blessed is the One in Whose Hands rests all authority. And He is Most Capable of everything.", tafsir: "تنزيه الله وتعظيمه، المالك لكل شيء، القادر على كل شيء." },
  { surahNumber: 67, verseNumber: 2, arabic: "الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ", translation: "He is the One Who created death and life in order to test which of you is best in deeds. And He is the Almighty, All-Forgiving.", tafsir: "خلق الله الموت والحياة ليختبر عباده فيعملوا الصالحات، وهو العزيز الغفور." },
  { surahNumber: 67, verseNumber: 3, arabic: "الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ ۖ فَارْجِعِ الْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ", translation: "He is the One Who created seven heavens, one above the other. You will never see any imperfection in the creation of the Most Compassionate. So look again: do you see any flaws?", tafsir: "خلق سبع سماوات طباقاً بلا تفاوت ولا اختلال." },
  { surahNumber: 67, verseNumber: 4, arabic: "ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ", translation: "Then look again and again—your sight will return frustrated and weary.", tafsir: "كر البصر فلا يرى عيباً، يرجع صاغراً حسيراً." },
  { surahNumber: 67, verseNumber: 5, arabic: "وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِّلشَّيَاطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ", translation: "Indeed, We adorned the lowest heaven with lamps stars and made them a source of missiles to drive away invisible devils, for whom We have also prepared a torment of the Blaze.", tafsir: "زيّن الله السماء بالنجوم، وجعلها رجوماً للشياطين، وأعد لهم عذاب السعير." },
  { surahNumber: 67, verseNumber: 6, arabic: "وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۚ وَبِئْسَ الْمَصِيرُ", translation: "For those who reject their Lord, there is the torment of Hell. What an evil destination!", tafsir: "للكافرين عذاب جهنم، وبئس المصير." },
  { surahNumber: 67, verseNumber: 7, arabic: "إِذَا أُلْقُوا فِيهَا سَمِعُوا لَهَا شَهِيقًا وَهِيَ تَفُورُ", translation: "When they are tossed into it, they will hear its roaring as it boils over,", tafsir: "إذا أُلقوا في جهنم سمعوا لها صوتاً منكراً وهي تغلي بهم." },
  { surahNumber: 67, verseNumber: 8, arabic: "تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ ۖ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ", translation: "almost bursting in fury. Every time a group is cast into it, its keepers will ask them scornfully: Did a warner not come to you?", tafsir: "تكاد جهنم تتقطع من الغيظ، والخزنة تسأل: ألم يأتكم نذير؟" },
  { surahNumber: 67, verseNumber: 9, arabic: "قَالُوا بَلَىٰ قَدْ جَاءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللَّهُ مِن شَيْءٍ إِنْ أَنتُمْ إِلَّا فِي ضَلَالٍ كَبِيرٍ", translation: "They will reply: Yes, a warner did come to us, but we rejected him and said: Allah has revealed nothing. You are solely lost in great error.", tafsir: "اعتراف الكفار بمجيء النذير وكذبهم به." },
  { surahNumber: 67, verseNumber: 10, arabic: "وَقَالُوا لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ", translation: "And they will further say: If only we had listened or reasoned, we would not be among the residents of the Blaze.", tafsir: "ندم الكفار يوم القيامة على عدم سماعهم وعقلهم." },
  { surahNumber: 67, verseNumber: 11, arabic: "فَاعْتَرَفُوا بِذَنبِهِمْ فَسُحْقًا لِّأَصْحَابِ السَّعِيرِ", translation: "Then they will confess their sin. So away with the residents of the Blaze!", tafsir: "اعترفوا بذنبهم فبعداً لأهل السعير." },
  { surahNumber: 67, verseNumber: 12, arabic: "إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", translation: "Indeed, those who fear their Lord without seeing Him will have forgiveness and a great reward.", tafsir: "للذين يخشون الله في الغيب مغفرة وأجر عظيم." },
  { surahNumber: 67, verseNumber: 13, arabic: "وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهُرُوا بِهِ ۖ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", translation: "Whether you conceal your words or declare them, He surely knows best what is hidden in everyone's heart.", tafsir: "سواء أسررتم القول أو جهرتم به، فالله عليم بما في الصدور." },
  { surahNumber: 67, verseNumber: 14, arabic: "أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ", translation: "Should He not know—He Who created? And He is the Subtle, the All-Aware.", tafsir: "كيف لا يعلم خالق الأشياء وهو اللطيف الخبير بها؟" },
  { surahNumber: 67, verseNumber: 15, arabic: "هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِ ۖ وَإِلَيْهِ النُّشُورُ", translation: "He is the One Who smoothed out the earth for you, so move about in its regions, eat from His provisions, and to Him is the resurrection of all.", tafsir: "سخر الله الأرض للسير فيها والأكل من رزقها، وإليه البعث." },
  { surahNumber: 67, verseNumber: 16, arabic: "أَأَمِنتُم مَّن فِي السَّمَاءِ أَن يَخْسِفَ بِكُمُ الْأَرْضَ فَإِذَا هِيَ تَمُورُ", translation: "Are you pagans not afraid that the One in heaven may cause the earth to swallow you up? Then suddenly it would rock back and forth in an earthquake.", tafsir: "أمنتم من استوى على العرش أن يخسف بكم الأرض فتمور بكم؟" },
  { surahNumber: 67, verseNumber: 17, arabic: "أَمْ أَمِنتُم مَّن فِي السَّمَاءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ", translation: "Or are you not afraid that the One in heaven may unleash upon you a storm of stones. Only then will you realize how true My warning was!", tafsir: "أمنتم أن يرسل الله عليكم حاصباً (ريحاً بحصى) فستعلمون كيف نذير." },
  { surahNumber: 67, verseNumber: 18, arabic: "وَلَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ", translation: "Indeed, many of those nations before them rejected their messengers, so how severe was My denial of them!", tafsir: "كذب الأمم السابقة رسلها فكيف كان إنكاري عليهم بالعذاب!" },
  { surahNumber: 67, verseNumber: 19, arabic: "أَوَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ صَافَّاتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَٰنُ ۚ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ", translation: "Have they not seen the birds above them, spreading and folding their wings? None holds them up except the Most Compassionate. Indeed, He is All-Seeing of everything.", tafsir: "الاستدلال بتسخير الطير في الجو على قدرة الله." },
  { surahNumber: 67, verseNumber: 20, arabic: "أَمَّنْ هَٰذَا الَّذِي هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ الرَّحْمَٰنِ ۚ إِنِ الْكَافِرُونَ إِلَّا فِي غُرُورٍ", translation: "Or who is this that would be an army for you to protect you except the Most Compassionate? The disbelievers are truly lost in delusion.", tafsir: "من ذا الذي يجند جنداً ينصركم من دون الله؟ الكافرون في غرور." },
  { surahNumber: 67, verseNumber: 21, arabic: "أَمَّنْ هَٰذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ ۚ بَل لَّجُّوا فِي عُتُوٍّ وَنُفُورٍ", translation: "Or who is this that would provide you with sustenance if He were to withhold His provision? In fact, they persist in arrogance and avoidance.", tafsir: "من يرزقكم إن منع الله رزقه؟ بل استمروا في طغيان ونفور." },
  { surahNumber: 67, verseNumber: 22, arabic: "أَفَمَن يَمْشِي مُكِبًّا عَلَىٰ وَجْهِهِ أَهْدَىٰ أَمَّن يَمْشِي سَوِيًّا عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ", translation: "Is the one who walks humbly falling on his face better guided than the one who walks upright on the Straight Path?", tafsir: "مثل الكافر كمن يمشي منكساً على وجهه، والمؤمن كمن يمشي معتدلاً على صراط مستقيم." },
  { surahNumber: 67, verseNumber: 23, arabic: "قُلْ هُوَ الَّذِي أَنشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ", translation: "Say, O Prophet: He is the One Who brought you into being and gave you hearing, sight, and intellect. Yet you hardly give any thanks.", tafsir: "الله الذي خلقكم ووهبكم السمع والبصر والفؤاد، قليلاً ما تشكرون." },
  { surahNumber: 67, verseNumber: 24, arabic: "قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ", translation: "Say: He is the One Who scattered you all across the earth, and to Him you will all be gathered.", tafsir: "الله الذي نشركم في الأرض، وإليه يحشركم." },
  { surahNumber: 67, verseNumber: 25, arabic: "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ", translation: "They argue: When will this threat come to pass, if what you say is true?", tafsir: "استعجال المشركين للعذاب استبعاداً له." },
  { surahNumber: 67, verseNumber: 26, arabic: "قُلْ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُّبِينٌ", translation: "Say, O Prophet: That knowledge is only with Allah, and I am only sent to give you clear warnings.", tafsir: "العلم بوقوع العذاب عند الله، والنبي نذير مبين." },
  { surahNumber: 67, verseNumber: 27, arabic: "فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هَٰذَا الَّذِي كُنتُم بِهِ تَدَّعُونَ", translation: "When they finally see the torment approaching, the faces of the disbelievers will be miserable. And it will be said: This is what you were calling for!", tafsir: "لما رأوا العذاب قريباً ساءت وجوههم، وقيل: هذا الذي كنتم تستعجلون." },
  { surahNumber: 67, verseNumber: 28, arabic: "قُلْ أَرَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَن يُجِيرُ الْكَافِرِينَ مِنْ عَذَابٍ أَلِيمٍ", translation: "Say: Consider: whether He destroys me and those with me, or has mercy on us, who will protect the disbelievers from a painful torment?", tafsir: "سواء أهلكنا الله أو رحمنا، فمن يحمي الكافرين من العذاب؟" },
  { surahNumber: 67, verseNumber: 29, arabic: "قُلْ هُوَ الرَّحْمَٰنُ آمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ", translation: "Say: He is the Most Compassionate. We have believed in Him, and in Him we trust. Soon you all will know who is clearly astray.", tafsir: "نحن آمنا بالرحمن وتوكلنا عليه، فستعلمون من هو في ضلال." },
  { surahNumber: 67, verseNumber: 30, arabic: "قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَاءٍ مَّعِينٍ", translation: "Say: Consider: if your water were to sink into the earth, then who else could bring you flowing water?", tafsir: "لو غاض ماؤكم في الأرض فمن يأتيكم بماء معين؟ توحيد الله وبيان قدرته." },
];

